<script lang="ts">
 import {untrack} from 'svelte';
 import {get,put} from '$lib/api';import {Button} from '$lib/components/ui/button';import SpeechPicker from '$lib/voices/SpeechPicker.svelte';
 type Profile={provider?:string;model?:string;voice_id?:string;mode?:string};type Speaker={language?:string;id:string;name:string;revision:number;profile:Profile;ready:boolean;issue?:string};
 type Setup={audio_mode?:string;project_id:string;scene_id:string;title:string;updated_at:string;duration:number;aspect_ratio:string;language:string;primary_provider:string;speakers:Speaker[];voices_ready:boolean;references_ready:boolean;storyboard_ready:boolean;has_shots:boolean};
 let {scene,onstate,oncontinue,onchanged,onask,disabled=false}:{scene:string;onstate?:(s:{blocking:boolean;loading:boolean})=>void;oncontinue?:()=>void|Promise<void>;onchanged?:()=>void;onask?:(text:string)=>void;disabled?:boolean}=$props();
 let setup=$state<Setup|null>(null),forms=$state<Record<string,Profile>>({}),configured=$state<Record<string,boolean>>({}),provider=$state('fal'),key=$state(''),keyError=$state(''),error=$state(''),loading=$state(false),saving=$state(false),matching=$state(false),notice=$state(''),reasons=$state<Record<string,string>>({});let seq=0;
 const missing=$derived(setup?.speakers.filter(s=>!s.ready)??[]);
 const providers=[{id:'fish',name:'Fish Audio'},{id:'elevenlabs',name:'ElevenLabs'},{id:'fal',name:'fal.ai · MiniMax'}];
 const canSave=$derived(missing.length>0&&missing.every(s=>!!forms[s.id]?.voice_id?.trim()&&!!configured[forms[s.id]?.provider??'fal']));
 function report(){onstate?.({blocking:!setup||!setup.voices_ready||!setup.references_ready||!setup.has_shots,loading})}
 async function load(id:string){const token=++seq;loading=true;saving=false;matching=false;error='';notice='';key='';keyError='';onstate?.({blocking:true,loading:true});try{const [state,connections]=await Promise.all([get(`/voice/scenes/${encodeURIComponent(id)}/setup`),get('/settings/providers')]);if(token!==seq)return;if(!Array.isArray(state.speakers))throw Error('Could not read scene setup');setup=state;configured=Object.fromEntries(connections.map((c:any)=>[c.name,c.configured]));provider=state.primary_provider??'fal';forms=Object.fromEntries(state.speakers.filter((s:Speaker)=>!s.ready).map((s:Speaker)=>[s.id,{provider:s.profile.provider??provider,model:s.profile.model??'auto',voice_id:s.profile.voice_id??''}]));reasons={};}catch(e){if(token===seq){setup=null;error=String(e)}}finally{if(token===seq){loading=false;report()}}}
 $effect(()=>{const id=scene;untrack(()=>void load(id))});
 async function saveKey(){
  if(!key.trim()||saving||matching||disabled)return;
  const token=seq,p=provider,secret=key.trim();keyError='';saving=true;
  try{await put(`/settings/providers/${p}`,{api_key:secret});if(token!==seq)return;configured[p]=true;if(provider===p)key='';error='';notice='Provider key saved. Model and voice access will be checked when loading the catalog.'}
  catch(e){if(token===seq)keyError=String(e)}finally{if(token===seq)saving=false}
 }
 function useProvider(){for(const row of missing)forms[row.id]={provider,model:'auto',voice_id:''};reasons={};notice='Provider applied to missing speakers. Existing ready voices are unchanged.'}
 async function matchAll(){if(!setup||saving||matching||disabled)return;matching=true;error='';notice='';const token=seq;const results=await Promise.allSettled(missing.map(async row=>{const p=forms[row.id]?.provider??provider;if(!['fish','elevenlabs'].includes(p))throw Error(`${row.name}: choose Fish Audio or ElevenLabs to match automatically, or enter a MiniMax saved voice ID`);if(!configured[p])throw Error(`${row.name}: save the ${p} key first`);const r=await get(`/voice/catalog/${p}/voices?character_id=${encodeURIComponent(row.id)}&language=${encodeURIComponent(row.language??setup?.language??'en')}`);return {row,p,result:r}}));if(token!==seq)return;const used=new Set(setup.speakers.filter(s=>s.ready).map(s=>(s.profile.provider??'fal')+':'+s.profile.voice_id));const failures:string[]=[];let matched=0;for(const result of results){if(result.status==='rejected'){failures.push(String(result.reason));continue}const {row,p,result:r}=result.value;const chosen=(r.voices??[]).find((v:any)=>!used.has(p+':'+v.id))??r.suggested;if(!chosen?.id){failures.push(row.name+': no voices found for the selected language');continue}matched++;forms[row.id].voice_id=chosen.id;used.add(p+':'+chosen.id);reasons[row.id]=chosen.id===r.suggested?.id?r.reason:`Selected an alternative returned voice (${chosen.name}) to keep speakers distinct. Audition before saving.`}matching=false;error=failures.join('\n');notice=matched?`Matched ${matched} of ${missing.length} missing voices. Adjust any voice below, then save the scene setup.`:'No voices matched. Configure the provider or choose saved voice IDs below.'}
 async function save(render=false){if(!setup||!canSave||saving||matching||disabled)return;saving=true;error='';const token=seq,id=scene;try{const state=await put(`/voice/scenes/${encodeURIComponent(id)}/setup`,{expected_updated_at:setup.updated_at,confirmed:true,profiles:missing.map(row=>({character_id:row.id,revision:row.revision,provider:forms[row.id].provider,model:forms[row.id].model??'auto',voice_id:forms[row.id].voice_id}))});if(token!==seq)return;for(const row of state.speakers){if(!row.ready&&!forms[row.id])forms[row.id]={provider:row.profile.provider??provider,model:row.profile.model??'auto',voice_id:row.profile.voice_id??''}}setup=state;report();onchanged?.();notice='All selected speaker voices saved.';if(render&&state.voices_ready&&state.references_ready&&state.has_shots)await oncontinue?.();}catch(e){if(token===seq)error=String(e)}finally{if(token===seq)saving=false}}
</script>
<section aria-label="Scene setup in chat" class="mt-3 space-y-3 rounded-lg border border-border p-3 text-sm">
 <div class="flex items-center justify-between gap-2"><h3 class="font-semibold">{setup?`Scene setup · ${setup.title}`:'Check scene setup'}</h3><Button variant="ghost" size="sm" disabled={loading||saving||disabled} onclick={()=>load(scene)}>Recheck</Button></div>
 {#if loading}<p role="status" class="text-muted-foreground">Checking all scene speakers and references…</p>{:else if setup}
 <p class="text-xs text-muted-foreground">{setup.duration}s · {setup.aspect_ratio}. Current saved scene settings.</p>
 <ul class="space-y-1 text-xs" aria-label="Scene prerequisites"><li>{setup.has_shots?'Shots ready':'Plan or add shots first'}</li><li>{setup.references_ready?'Character and asset references ready':'Some character or asset references are missing, unavailable or excluded'}</li><li>{setup.storyboard_ready?'Matching storyboard ready':'Storyboard will update before rendering'}</li></ul>
 {#if !setup.has_shots||!setup.references_ready}<p class="text-xs text-muted-foreground">Resolve the missing scene inputs before rendering. Existing saved work is kept.</p>{#if onask}<div class="flex flex-wrap gap-2">{#if !setup.has_shots}<Button variant="outline" size="sm" onclick={()=>onask?.(`Plan shots for ${setup?.title}`)}>Plan shots in chat</Button>{/if}{#if !setup.references_ready}<Button variant="outline" size="sm" onclick={()=>onask?.(`Help resolve the missing or excluded character and asset reference images for ${setup?.title}. Keep existing usable images; do not unexclude images automatically.`)}>Fix references in chat</Button>{/if}</div>{/if}{/if}
 {#if missing.length}
 <p>{missing.length} {missing.length===1?'speaker needs':'speakers need'} a saved voice. Set them up together here.</p>
 <label class="block text-xs font-medium">Provider for missing voices<select aria-label="Provider for missing voices" class="mt-1 min-h-11 w-full rounded-md border border-input bg-background p-2" bind:value={provider} onchange={()=>{key='';keyError='';useProvider()}} disabled={saving||matching||disabled}>{#each providers as p}<option value={p.id}>{p.name}{p.id===setup.primary_provider?' · Primary':''}</option>{/each}</select></label>

 {#if !configured[provider]}<div class="space-y-2"><p class="text-xs text-muted-foreground">Save this provider key here. It stays on the backend and is never added to conversation text.</p><label class="block text-xs font-medium">Provider API key<input aria-label="Provider API key" class="mt-1 min-h-11 w-full rounded-md border border-input bg-background p-2" type="password" autocomplete="off" disabled={saving||matching||disabled} bind:value={key}/></label><Button variant="outline" size="sm" disabled={saving||!key.trim()||disabled} onclick={saveKey}>Save provider key</Button>{#if keyError}<p role="alert" class="text-destructive">{keyError}</p>{/if}</div>{/if}
 <Button variant="outline" disabled={matching||saving||disabled} onclick={matchAll}>{matching?'Matching speakers…':'Match all missing voices'}</Button>
 {#each setup.speakers as row (row.id)}{#if row.ready}<p class="text-xs text-muted-foreground">{row.name} · Saved voice ready, kept unchanged</p>{:else}{@const form=forms[row.id]}<details class="border-t border-border pt-2"><summary class="min-h-11 cursor-pointer py-2 font-medium">{row.name} · {form.voice_id?'Voice selected':'Choose voice'}</summary><fieldset disabled={saving||matching||disabled}><p class="mb-2 text-xs text-muted-foreground">{row.issue}</p><label class="block text-xs font-medium">Speech provider<select aria-label={`Speech provider for ${row.name}`} class="my-1 min-h-11 w-full rounded-md border border-input bg-background p-2" bind:value={form.provider} onchange={()=>{form.voice_id='';form.model='auto';reasons[row.id]=''}}>{#each providers as p}<option value={p.id}>{p.name}</option>{/each}</select></label>{#if !configured[form.provider??'fal']}<Button variant="outline" size="sm" onclick={()=>{provider=form.provider??'fal';key='';keyError=''}}>Configure this provider above</Button>{/if}{#if form.provider==='fish'||form.provider==='elevenlabs'}<SpeechPicker provider={form.provider} character={row.id} bind:model={form.model} bind:voice={form.voice_id} onchange={()=>{}}/>{/if}<label class="mt-2 block text-xs font-medium">Saved voice ID<input aria-label={`Saved voice ID for ${row.name}`} class="mt-1 min-h-11 w-full rounded-md border border-input bg-background p-2" bind:value={form.voice_id}/></label>{#if reasons[row.id]}<p role="status" class="mt-1 text-xs text-muted-foreground">{reasons[row.id]}</p>{/if}</fieldset></details>{/if}{/each}
 <p class="text-xs text-muted-foreground">Saving uses these chosen saved voices for the speakers. It does not clone voices or generate speech.</p><div class="flex flex-wrap gap-2"><Button variant="outline" disabled={!canSave||saving||matching||disabled} onclick={()=>save()}>Save all voices</Button>{#if oncontinue}<Button disabled={!canSave||saving||matching||disabled||!setup.has_shots||!setup.references_ready} onclick={()=>save(true)}>{saving?'Saving…':'Save voices & render'}</Button>{/if}</div>
 {:else}<p role="status" class="text-xs">{setup.audio_mode==='native'?'Native audio selected. No saved voices needed.':setup.audio_mode==='silent'?'Silent video selected. No voices needed.':'All scene speaker voices are ready. Existing bindings are kept.'}</p>{/if}
 <p class="text-xs text-muted-foreground">{setup.audio_mode==='native'?'Native audio is generated with the video. Saved character voices and exact speech timing remain optional separate tools.':setup.audio_mode==='silent'?'Rendering creates a silent video. Add a soundtrack in the editor if needed.':'Rendering creates the visual clip. Exact dialogue audio and visible-speaker lip sync remain separate speech steps.'} Image/video generation may use credits.</p>
 {/if}
 {#if notice}<p role="status" class="text-xs">{notice}</p>{/if}{#if error}<p role="alert" class="whitespace-pre-wrap text-xs text-destructive">{error}</p>{/if}
</section>
